        self.cardVO = UITaskGrowUpPanelUtils.ReadCardVO(self.themeVO.bigReward)     -- 角色卡牌表
        self.cardGoodsVO = UITaskGrowUpPanelUtils.ReadCardGoodsVO(self.themeVO.bigReward)     -- 卡牌道具表


        -- 领取 本组的所有宝箱 配表数据:
        self:InitAllChestDatas( self.themeVO.targetGroup )
        -- 配置 宝箱实例 的刷新函数:
        -- 为支付 LoopGridView 自动吸附功能, 故意在 原定宝箱链表首尾添加两个宝箱实例(隐藏的)


        -- 初始化 宝箱链表 系统: -- !!! 现在延迟到读取后端数据之后 
        --self:RefreshAllChests() 

        -- 每当 LoopGridView 切换 吸附宝箱, 都要跟换下方的 文本内容:
        self.ChestLoopGrid.mOnSnapNearestChanged = function( LoopGridView_ )
            -- LoopGridView_.CurSnapNearestItemRowColumn.mColumn: [0, self.chestCount-1]
            local near = LoopGridView_.CurSnapNearestItemRowColumn -- RowColumnPair

            local newSnappedChestIdx = near.mColumn + 1 -- [1, self.chestCount]
            if newSnappedChestIdx ~= self.currentSnappedChestIdx then 
                self.currentSnappedChestIdx = newSnappedChestIdx
                self:RefreshChestInfo( self.currentSnappedChestIdx, false )
            end 
        end

        -- 读后端: task/growthTask:
        self:CallServer_GrowthTask( self.themeId )

        -- 显示右上角文本: "以下四名战斗员搭配适合新手阵容"
