        -- 左侧角色皮肤 (大半身像)
        self.BossDrawingNode:Execute( self.cardVO.defaultSkin )

        -- 左侧的: "「小白·AI助理」" 
        self.TxtWillGet.text = "「" .. self.cardVO.descr .. "·" .. self.cardVO.name .."」"

        -- 左侧 SSR 组件UI内容 + 按钮:
        self:InitCommonBtnRoleNameNode() 

    end))
    return coWait
end




