-- 刷新宝箱下方的 提示信息
function UITaskGrowUpSecondPanel:RefreshChestInfo( snapChestIdx_, isFirstIn_ )

    if self.co_2 ~= nil then
        --print( "koko  强行终止 刷新宝箱下方的提示信息 的协程 并重启它" ) -- 触发率高, 且可接受
        cs_coroutine.stop(self.co_2)
    end
    self.co_2 = cs_coroutine.start(function()
        -- 

        local snapChestId = self.chestGroupIdList[ snapChestIdx_ ]
        local snapChestData = self.chestGroupVODict[ snapChestId ]

        -- 初入 二级页面 时, 后端调用可能未返回, 此时必须等到数据准备完善:
        while isNull(snapChestData.luaEnv) or type(self.boxesDojo)~="table" or table.count(self.boxesDojo)~=self.chestCount do 
            coroutine.yield(Yielders.EndOfFrame)
        end

        local snapChestSate = snapChestData.luaEnv.chestState
        local snapChestVO = UITaskGrowUpPanelUtils.ReadGrowUpChestVO( self.chestGroupIdList[ snapChestIdx_ ] )
        local boxDojo = self.boxesDojo[snapChestIdx_]

        -- 关闭动画
        if isFirstIn_ == false then 
            coroutine.yield(Yielders.EndOfFrame)
            CfUtils.PlayAnimation(self.AnimBelowChest, Anim_BelowChest_Close )
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.1 ))
        end

        -- 打开动画
        CfUtils.SetActive( self.AnimBelowChest.gameObject, true ) -- 打开 提示信息 层级
        CfUtils.PlayAnimation(self.AnimBelowChest, Anim_BelowChest_Open )

        -- 当前宝箱下方的 "达成目标:XXX" 文本
        self.TxtBelowChest.text = localize("达成目标:_Target_(_Progress_/4)", {_Target_ = snapChestVO.desc, _Progress_=table.count(boxDojo.finishTaskIds)} )

        -- 根据 "当前宝箱" 不同状态, 显示 不同效果
        -- 达成目标时 文字颜色变浅
        CfUtils.SetUISwitchText(self.TxtBelowChest.gameObject, (snapChestSate == ChestState.Finshed and 2 or 1) )
        -- 锁定状态时 画锁
        CfUtils.SetActive(self.LockBelowChest.gameObject, (snapChestSate == ChestState.Locked) )
        -- 达成目标时 画横线
        CfUtils.SetActive(self.ImgLineBelowChest.gameObject, (snapChestSate == ChestState.Finshed) )
    end) 
end


