-- 根据 宝箱组id, 读取本组所有宝箱的 配表数据, 并将它们串成链表数据
---@param chestGroupId_ integer @ 宝箱组id
function UITaskGrowUpSecondPanel:InitAllChestDatas( chestGroupId_ )
    if type(chestGroupId_) ~= "number" then 
        printError( "参数 宝箱组id 异常" )
        return
    end

    -- 读取 宝箱组 配表:
    ---@type UITaskGrowUpChestVO
    local chestGroupsVO = UITaskGrowUpPanelUtils.ReadGrowUpChestVOByGroup( chestGroupId_ ) -- 成长任务宝箱表, 一个组的
    if isNull(chestGroupsVO) or table.count(chestGroupsVO) == 0 then 
        printError( "读取 宝箱组 配表数据异常, 请检查" )
        return
    end 

    -- 配表数据可能有错, 我们暂时假定 组首元素一定在链表头, 且后续元素一定一个连一个:
    self.chestGroupVODict = {} -- dictionary:  { k = chestId, v = chest vo }
    self.chestGroupIdList = {} -- list:        [ chestId ]  用数组来存储 静态链表 信息;

    local tmpId = nil
    -- 将全组vo数据 全部装入 chestGroupVODict
    for k,vo_ in pairs(chestGroupsVO) do 
        local _chestId = vo_.taskAchId
        if k == 1 then 
            tmpId = _chestId
        end 
        self.chestGroupVODict[_chestId] = { 
            luaEnv = nil,
            params = { 
                chestIdx = 0,
                chestId = _chestId,
                chestVO = vo_,  -- 本行宝箱配表数据
                isLast = false,                
                boxDojo = nil,  -- "task/growthTask".data.box[i] / "task/drawGrowthTaskRewards".data.box[i]
            }
        }
    end

    -- 将链表内的 chestId 值装入 chestGroupIdList
    -- 若配表某一行的 after 为 0 或 异常值, 这一行即被判定为 链表的最后一个元素
    while isNotNull( self.chestGroupVODict[tmpId] )  do
        table.insert( self.chestGroupIdList, tmpId )
        tmpId = self.chestGroupVODict[tmpId].params.chestVO.after -- next
        if tmpId == 0 then 
            break
        end 
    end 

    self.chestCount = table.count( self.chestGroupIdList )

    -- 将 chestGroupVODict 中部分数据补完:
    for _chestIdx, _chestId in pairs( self.chestGroupIdList ) do 
        local pa = self.chestGroupVODict[_chestId].params
        pa.chestIdx = _chestIdx
        pa.chestId = _chestId
        -- 链表最后一个元素 要设置:
        if _chestIdx == self.chestCount then 
            pa.isLast = true
        end 
    end 

    self:Debug_Chests()
end




-- LoopGridView 使用 宝箱对象池 来管理各宝箱, 当玩家拖动屏幕, 一个新宝箱出现在屏幕中时, 这个 宝箱实例 是从 对象池 里随机拿出来的元素 
-- 所以为了确保 绘制正确, 每次调用本函数, 都要将新宝箱 彻底重绘制一遍;
---@param index integer @ 0-based
function UITaskGrowUpSecondPanel:OnCreateChestByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("RewardNode")
    local node = GetLuaBehaviour(cell.gameObject, "Game.UI.Tasks.UITaskGrowUpRewardNode" )

    ---@type UITaskGrowUpRewardNode
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
        nodeEnv = node.Env
    else
        nodeEnv = node.Env
    end

    -- index -- [0, self.chestCount+2-1]
    local oneBasedIdx = index + 1 -- [1, self.chestCount+2]
    local chestIdx = oneBasedIdx - 1 -- 去掉目前 链表的首尾元素: {0, self.chestCount+2-1}, 所以元素区间为: [1,self.chestCount]

    -------------------------------------------
    if nodeEnv then

        if oneBasedIdx == 1  then 
            -- 链表首节点, 空的不显示, 为支持 "吸附功能" 而存在
            nodeEnv:SetShowOrHide( false )

        elseif oneBasedIdx == (self.chestCount+2) then
            -- 链表尾节点, 空的不显示, 为支持 "吸附功能" 而存在
            nodeEnv:SetShowOrHide( false )
        else 
            local chestId = self.chestGroupIdList[chestIdx]
            local chestData = self.chestGroupVODict[chestId]
            chestData.luaEnv = nodeEnv

            nodeEnv:SetShowOrHide( true )
            self:RefreshSingleChest( chestData, true, "自动刷新宝箱: " )
        end

    else 
        printError( "宝箱实例 生成时出现异常, 请检查" )
    end
    ---
    return cell
end


-- 在刚进入 二级页面时, 主动将 "当前宝箱" 放到 链表中央位置:
function UITaskGrowUpSecondPanel:SetCurrentChestToCenter()

    if self.currentChestIdx~=-1 and self.ChestLoopGrid then 
        -- 链表窗口内共显示 3 个宝箱, 本函数设置的是 左侧第一个元素的 idx;
        -- 所以要找到一个 0-based "当前宝箱左侧宝箱" 的 idx;
        self.ChestLoopGrid:MovePanelToItemByRowColumn( 0, self.currentChestIdx-1+1-1 ) -- 减1 是因为 本函数参数需要 0-based; 加1是因为存在额外的 头部空元素; 减1 是以为要传入 "当前左侧宝箱" 的 idx
    else 
        printError( "数据异常" )
    end
end



-- 手动刷新 所有 宝箱 (数据与绘制):
function UITaskGrowUpSecondPanel:RefreshAllChests()
    if not self.ChestLoopGrid.IsListViewInit then
        -- 初始化
        self.ChestLoopGrid:InitGridView( self.chestCount + 2, Bind(self, self.OnCreateChestByIndex) , nil, loopGridViewInitParam ) -- 此 callback 应该是在下一帧 update 中被执行的
    else
        -- 复刷
        GameUtils.ReloadData(self.ChestLoopGrid, self.chestCount + 2 )
    end  
end



function UITaskGrowUpSecondPanel:RefreshSingleChest( chestData_, isIgnoreNilBoxesDojo_, debugHeadStr_ )

    local chestParams = chestData_.params
    chestParams.boxDojo = nil
    if type(self.boxesDojo)=="table" then 
        if table.count(self.boxesDojo) == self.chestCount then 
            chestParams.boxDojo = self.boxesDojo[chestParams.chestIdx]
        else 
            printError( "boxesDojo 数据异常" )
        end
    else 
        if isIgnoreNilBoxesDojo_ ~= true then 
            printError( "boxesDojo 为 nil" )
        end
    end 
    --print( tostring(debugHeadStr_) .. self:Print_ChestsParams( chestParams ) ) -- todo: debug
    ---
    chestData_.luaEnv:FreshUI( chestParams, self ) 
end



-- 读后端: task/growthTask
function UITaskGrowUpSecondPanel:CallServer_GrowthTask( themeId_ )

    GameUtils.Request( Interfaces.GrowUpGrowthTask, { themeId =  themeId_  }, function(request, response) -- "task/growthTask"
        if checkNumber(response.errCode) == 0 then 

            self.growthTaskDojo = response.data
            if not (self.growthTaskDojo and self.growthTaskDojo.box and self.growthTaskDojo.task ) then 
                printError( "后端数据异常, 请检查" )
                return
            end

            -- 刷新 boxesDojo 数据缓存:
            self:RefreshBoxesDojo( self.growthTaskDojo.box )

            self:RefreshAllChests()                                     -- 刷新 全部 宝箱数据: (避免下方代码访问不到)

            -- 当进入 二级页面 时, 要主动将 "当前宝箱" 居中放置:
            if self.isInitSetChestPos == false then 
                self.isInitSetChestPos = true 
                self:SetCurrentChestToCenter() -- 将 "当前宝箱" 居中
                -- 第一次显示 宝箱下的文本框:
                self.currentSnappedChestIdx = self.currentChestIdx
                self:RefreshChestInfo( self.currentSnappedChestIdx, true ) -- 刷新 宝箱下方文本
            end 

            self:RefreshTasks( themeId_, self.growthTaskDojo.task )     -- 刷新 全部 4条 任务数据:
            self:RefreshClaimAllRewardsButton()                         -- 更新 "一键领取" 按钮的状态:
            self:RefreshAllChests()                                     -- 刷新 全部 宝箱数据:  (再次刷新)
            self:RefreshTaskRedPoint()                                 
        end
    end)
end



-- 点击 任务条上 点击 "领取奖励" 按钮, 
function UITaskGrowUpSecondPanel:CallServer_DrawGrowthTaskRewards( themeId_, taskId_ )

    GameUtils.Request( Interfaces.GrowUpDrawGrowthTaskRewards, { themeId = themeId_, taskId = taskId_ }, function(request, response) -- "task/drawGrowthTaskRewards"
        if checkNumber(response.errCode) == 0 then 

            local drawGrowthTaskRewardsDojo = response.data
            if not ( drawGrowthTaskRewardsDojo and drawGrowthTaskRewardsDojo.box and drawGrowthTaskRewardsDojo.task and drawGrowthTaskRewardsDojo.rewards ) then 
                printError( "后端数据异常, 请检查" )
                return
            end

            -- 刷新 boxesDojo 数据缓存:
            self:RefreshBoxesDojo( drawGrowthTaskRewardsDojo.box )

            -- 领取奖励-存储数据:
            GoodsUtils.DrawRewards( drawGrowthTaskRewardsDojo.rewards )

            -- cb: 领取奖励打脸界面被关闭后, 会执行的内容:
            CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, {rewards = drawGrowthTaskRewardsDojo.rewards, cb = function()

                self:RefreshChestInfo( self.currentSnappedChestIdx, true )          -- 刷新 宝箱下方文本
                self:RefreshTasks( themeId_, drawGrowthTaskRewardsDojo.task )       -- 刷新 全部 4条 任务数据:
                self:RefreshClaimAllRewardsButton()                                 -- 更新 "一键领取" 按钮的状态:
                self:RefreshAllChests()                                             -- 刷新 全部 宝箱数据:                
                self:RefreshTaskRedPoint()                                            
            end})
        end
    end)
end



function UITaskGrowUpSecondPanel:RefreshTaskRedPoint()
    GameUtils.SetRedPointNum( Constants.RedPointConst.GrowUpTask, ( self.currentCanDrawedTaskNum > 0 and 1 or 0 ) )
    print( "koko - 修改 成长任务 小红点: task: " .. tostring( self.currentCanDrawedTaskNum > 0 and 1 or 0 ) )
end


-- 点击 宝箱 上 "领取奖励" 按钮, 
function UITaskGrowUpSecondPanel:CallServer_DrawGrowthBoxRewards()
    if isNull(self.themeId) or (self.currentChestIdx==-1) or (self.currentChestIdx > self.chestCount) then 
        printError( "数据 themeId, currentChestIdx 异常, 放弃领取宝箱" )
        return
    end

    -- 先主动熄灭当前 宝箱小红点
    -- 如果下一个宝箱还能领取, 后端会在本次调用结束后, 用长连接把 宝箱红点再次点亮
    GameUtils.SetRedPointNum(Constants.RedPointConst.GrowUpTaskBox, 0 )
    print("koko 成长任务 熄灭宝箱红点: -> 0" )

    ---
    local nowChestIdx = self.currentChestIdx
    local chestId = self.chestGroupIdList[nowChestIdx]
    GameUtils.Request( Interfaces.GrowUpDrawGrowthBoxRewards, { themeId = self.themeId, boxId = chestId }, function(request, response) -- "task/drawGrowthBoxRewards"
        if checkNumber(response.errCode) == 0 then 

            local drawGrowthBoxRewardsDojo = response.data
            if not ( drawGrowthBoxRewardsDojo and drawGrowthBoxRewardsDojo.rewards ) then 
                printError( "后端数据异常, 请检查" )
                return
            end

            -- 领取奖励打脸界面:
            GoodsUtils.DrawRewards( drawGrowthBoxRewardsDojo.rewards )

            -- 领取奖励打脸界面 被关闭后, 会执行的内容:
            CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, {rewards = drawGrowthBoxRewardsDojo.rewards, cb = function()

                self:RefreshAllChests()                                     -- 刷新 全部 宝箱数据: (避免下方代码访问不到)

                -- 当前宝箱 指向下一位
                if self.currentChestIdx < self.chestCount then 
                    self.currentChestIdx = self.currentChestIdx + 1
                    self:SetCurrentChestToCenter()
                end 
                
                self:RefreshChestInfo( self.currentSnappedChestIdx, true )          -- 刷新 宝箱下方文本
                self:RefreshAllChests()                                             -- 刷新 全部 宝箱数据: (再次刷新)

                -- 领取完最后一个宝箱后, 自动返回 "任务主页面":
                if nowChestIdx == self.chestCount then 
                    UIModule.BackDialog()
                end
            end})

        end
    end)
end


-- 从 "task/growthTask".data.box or "task/drawGrowthTaskRewards".data.box 二选一中拿到的 数据, 做一点检测和缓存
function UITaskGrowUpSecondPanel:RefreshBoxesDojo( boxesDojo_ )
    self.boxesDojo = nil
    self.currentChestIdx = -1
    ---
    if type(boxesDojo_)~="table" or table.count(boxesDojo_)~=self.chestCount then 
        printError( "boxesDojo 后端数据异常" )
        return
    end 
    ---
    self.boxesDojo = boxesDojo_
    ---
    local findIdx = nil
    for _idx,_dojo in pairs(self.boxesDojo) do 
        if _dojo.isCurrentBox == 1 then 
            if findIdx == nil then 
                findIdx = _idx
            else 
                printError( "后端数据异常, 出现多个 box.isCurrentBox 值为 1" )
                -- 但并不做处理, 等于将这个异常值放弃了
            end
        end 
    end
    if findIdx == nil then 
        printError( "后端数据异常, 未找到任何 box.isCurrentBox 值为 1" )
    end 
    self.currentChestIdx = findIdx
end 


-- 初始阶段, 所有 任务条 都是关着的:
function UITaskGrowUpSecondPanel:ShowAllTasks()
    if self.isInitAllTasks == true then
        printError("koko  重复调用")
        return
    end

    assert( self.TaskCellNode1 and self.TaskCellNode2 and self.TaskCellNode3 and self.TaskCellNode4  )

    CfUtils.SetActive( self.TaskCellNode1.gameObject, true )
    CfUtils.SetActive( self.TaskCellNode2.gameObject, true )
    CfUtils.SetActive( self.TaskCellNode3.gameObject, true )
    CfUtils.SetActive( self.TaskCellNode4.gameObject, true )

    local taskNodeLuaPath = "Game.UI.Tasks.UITaskGrowUpTaskNode"
    local TaskCellNodeEnv1 = CfUtils.GetLuaScr(self.TaskCellNode1.gameObject, taskNodeLuaPath )
    local TaskCellNodeEnv2 = CfUtils.GetLuaScr(self.TaskCellNode2.gameObject, taskNodeLuaPath )
    local TaskCellNodeEnv3 = CfUtils.GetLuaScr(self.TaskCellNode3.gameObject, taskNodeLuaPath )
    local TaskCellNodeEnv4 = CfUtils.GetLuaScr(self.TaskCellNode4.gameObject, taskNodeLuaPath )
    if not (TaskCellNodeEnv1 and TaskCellNodeEnv2 and TaskCellNodeEnv3 and TaskCellNodeEnv4) then 
        printError("koko - 成长任务二级页面 taskNode lua env 获取失败")
        return
    end 
    self.TaskCellNodeEnvs = { TaskCellNodeEnv1, TaskCellNodeEnv2, TaskCellNodeEnv3, TaskCellNodeEnv4 }

    for _,taskEnv in pairs(self.TaskCellNodeEnvs) do 
        taskEnv:SelfInit()
    end 

    self.isInitAllTasks = true
end



-- 刷新 二级页面 右侧 4条 任务条 的内容:
function UITaskGrowUpSecondPanel:RefreshTasks( themeId_, tasksDojo_ )
    if self.isInitAllTasks ~= true then
        self:ShowAllTasks()
    end

    -- 刷新 4 条 task ui: 
    for i=1,4  do 
        self.TaskCellNodeEnvs[i]:FreshUI({ 
            taskIdx = i, -- 1-based
            taskDojo = tasksDojo_[i], -- "task/growthTask" / "task/drawGrowthTaskRewards" 里的 task 容器
            themeId = themeId_,
            secondPanelEnv = self,
        })
    end
end


-- 更新 "一键领取" 按钮的状态
function UITaskGrowUpSecondPanel:RefreshClaimAllRewardsButton()
    if self.isInitClaimAllRewardsButton ~= true then 
        SetButtonAction(self.ClaimAllRewardsButton, Bind(self, self.OnClickBatchDrawHandler))
        self.isInitClaimAllRewardsButton = true
    end
    ---
    self.currentCanDrawedTaskNum = 0
    for i=1,4  do 
        if self.TaskCellNodeEnvs[i].taskState == TaskState.WaitToGetRewards then
            self.currentCanDrawedTaskNum = self.currentCanDrawedTaskNum + 1
        end
    end
    CfUtils.SetActive(self.ClaimAllRewardsButton.gameObject, (self.currentCanDrawedTaskNum > 0) )
end



function UITaskGrowUpSecondPanel:OnClickBatchDrawHandler()
    if self.currentCanDrawedTaskNum <= 0 then 
        printError("一键领取按钮 异常存在")
        return
    end
    print( "一键领取按钮" )
    self:CallServer_DrawGrowthTaskRewards( self.themeId, 0 )
end


function UITaskGrowUpSecondPanel:Debug_Chests()
    print( "koko --------- 宝箱数据 --------------" )
    for _chestIdx, _chestId in pairs( self.chestGroupIdList ) do 
        local pa = self.chestGroupVODict[_chestId].params

        local ll =  "== Idx: " .. tostring(_chestIdx) .. ",  Id: " .. tostring(_chestId)
        ll =  ll .. self:Print_ChestsParams(pa)
        print( ll )
    end
end


function UITaskGrowUpSecondPanel:Print_ChestsParams( chestParams_ )
    local ll =   
                "\n    chestIdx: " .. tostring(chestParams_.chestIdx) .. 
                "\n    chestId:  " .. tostring(chestParams_.chestId) .. 
                "\n    currentChestIdx: " .. tostring(chestParams_.currentChestIdx) .. 
                "\n    chestVO: " .. tostring(chestParams_.chestVO) .. 
                "\n    isLast:  " .. tostring(chestParams_.isLast) .. 
                "\n    boxDojo: " .. tostring(chestParams_.boxDojo)
    return ll
end


return UITaskGrowUpSecondPanel


